using System.Windows.Forms;

internal sealed class BotHelp : UserControl
{
    private static readonly string[][] Chapters =
    {
        new[] { "Erster Start und Installation", "Lade das Windows-Setup aus dem aktuellen GitHub-Release herunter und öffne die Datei TikTok-Bot-Setup.exe. Wähle im Setup bei Bedarf das Desktop-Symbol. Starte den Bot über dieses Symbol oder das Startmenü.\n\nWenn die App meldet, dass WebView2 fehlt, installiere die Microsoft Edge WebView2 Runtime. Deine Einstellungen und Browserprofile liegen im lokalen Windows-Benutzerprofil und werden beim normalen Update weiterverwendet.\n\nFür den ersten Test: Melde das Bot-Konto an, speichere dein LIVE-Konto und starte anschließend einen echten TikTok-Livestream." },
        new[] { "Bot-Konto anmelden und Namen ändern", "Öffne Einstellungen → Bot-Konto → Bei TikTok anmelden. Melde dich direkt in der TikTok-Webansicht mit dem Konto an, das später im Chat schreiben soll.\n\nSobald die Sitzung erkannt ist, zeigt der Bot „Bot-Konto angemeldet“. Trage bei Bedarf den öffentlichen @Namen ein und klicke auf @Name speichern. Dieser gespeicherte Name allein meldet dich nicht an.\n\nÜber Bot-Profil / Spitzname ändern öffnest du das TikTok-Profil. Wähle dort Profil bearbeiten und speichere den neuen Spitznamen bei TikTok." },
        new[] { "Festes LIVE-Konto und Verbindung", "Klicke oben auf Streamer ändern. Gib den @Namen des Streamers oder dessen TikTok-LIVE-Link ein und klicke auf Streamer speichern. Das LIVE-Konto bestimmt, aus welchem Stream der Bot liest. Das Bot-Konto bestimmt, unter welchem Namen er schreibt.\n\nNutze LIVE öffnen zum direkten Öffnen oder aktiviere LIVE automatisch prüfen. Rot und „Nicht live“ bedeuten, dass der Bot gerade keinen laufenden LIVE-Chat bestätigt hat. Grün und „LIVE verbunden“ zeigt die aktive Verbindung an.\n\nZum Wechseln speichere ausdrücklich ein anderes LIVE-Konto. Über Einstellungen → TikTok-Webansicht siehst du die Seite und den Chat." },
        new[] { "Kommentare, Stimmen und Geschenke", "Öffne Kommentare und Stimme. Aktiviere Kommentare vorlesen, wenn der Bot gewöhnliche Chatnachrichten sprechen soll. Wähle Stimme und Stil. Stelle Lautstärke und Tempo in Prozent ein und prüfe das Ergebnis mit Stimme testen.\n\nDie Stimmwerte werden gespeichert. Über Stimme speichern kannst du das Speichern ausdrücklich auslösen. Beim nächsten Start werden die gespeicherten Werte geladen.\n\nWenn du nur Geschenke hören möchtest, lasse Kommentare vorlesen aus und aktiviere Geschenke ansagen und danken. Der Bot sagt zuerst das Geschenk an und spricht danach den Dank. Probiere beides mit Geschenkansage testen. TikTok-LIVE-Ton stumm schaltet den Ton des eingebetteten Streams ab." },
        new[] { "Chatantworten testen und senden", "Öffne Chatantworten. Wähle ein Beispiel oder gib im Feld Testkommentar etwa „Wie kann ich mir ein Lied wünschen?“ ein. Klicke auf Testen. Das Ergebnis erscheint nur in der App.\n\nAktiviere LIVE-Kommentare automatisch prüfen für Vorschläge aus dem echten Chat. Schalte zusätzlich Antworten automatisch in TikTok senden ein, wenn das angemeldete Bot-Konto schreiben soll. Der Bot braucht dazu das Sendefeld im verbundenen LIVE-Chat. In der Statuszeile siehst du, wenn Senden gerade nicht möglich ist.\n\nFür manuelles Senden wähle den Vorschlag, klicke Antwort kopieren und füge den Text im TikTok-Chat ein. Für Fragen zum Spiel trage den Spielnamen ein und klicke Spiel speichern." },
        new[] { "Eigene Antworten und lokale KI", "Klicke unter Chatantworten auf Neue Antwort. Trage eine typische Zuschauerfrage und deine Antwort ein. Klicke auf Antwort speichern. Zum Ändern wählst du den Eintrag, bearbeitest ihn und speicherst erneut.\n\nAktiviere Lokale KI, wenn die mitgelieferte KI auch für unbekannte Fragen einen Vorschlag versuchen soll. Sie läuft auf dem PC. Prüfe ihre Antworten mit Testen, bevor du den automatischen Versand nutzt.\n\nMit Lernvorschläge aus dem LIVE sammeln legt der Bot geeignete KI-Vorschläge lokal ab. Wähle einen Vorschlag, klicke auf Lernvorschlag bearbeiten, korrigiere ihn bei Bedarf und speichere ihn als eigene Antwort." },
        new[] { "Musikwünsche einrichten", "Öffne Musik. Aktiviere #Musikwunsch aus LIVE-Chat übernehmen und wähle als Musikquelle Lokale Dateien, Spotify, YouTube Music oder YouTube. Der Bot verwendet die gewählte Quelle für neue LIVE-Wünsche.\n\nEin Zuschauer schreibt beispielsweise #Musikwunsch Nena – 99 Luftballons. Der Wunsch erscheint in der App und die Glocke zeigt einen neuen Eintrag. Bei mehreren Spotify-Treffern antwortet die anfragende Person mit 1, 2 oder 3. Die Auswahl bleibt drei Minuten gültig.\n\nDie Warteschlange bestimmt, was als Nächstes läuft. Die Wunschliste im Bot zeigt eingegangene Wünsche. Der periodische Hinweistext für Zuschauer erscheint zum Kopieren im Musikbereich." },
        new[] { "Lokale Audiodateien", "Öffne Musik → Lokale Dateien und klicke auf Dateien hinzufügen. Wähle deine Audiodateien aus. Mit Abspielen, Überspringen und Stopp steuerst du die Wiedergabe.\n\nFür LIVE-Wünsche stelle die Musikquelle auf Lokale Dateien. Der Bot sucht in den Dateinamen. Benenne deine Dateien mit Künstler und Titel, damit er sie leichter findet.\n\nAktiviere Musikwünsche lokal automatisch abspielen, wenn ein gefundener Titel bei freiem Player direkt starten soll. Stelle die Lautstärke im selben Reiter ein." },
        new[] { "Spotify Premium einrichten", "Erstelle im Spotify-Entwicklerdashboard eine App, wähle Web API und trage als Redirect-URI genau http://127.0.0.1:43821/spotify/ ein. Kopiere die Client-ID aus dem Dashboard.\n\nÖffne Musik → Spotify-Warteschlange, füge die Client-ID ein und klicke Spotify verbinden. Bestätige die Freigabe im Browser. Starte anschließend einen Titel in Spotify Premium, damit Spotify ein aktives Wiedergabegerät hat.\n\nGib zum Test einen Titel oder Spotify-Link ein. Klicke bei einer Textsuche auf Titel suchen, wähle einen Treffer und klicke Zur Spotify-Warteschlange hinzufügen. Schau in Spotify unter Warteschlange nach.\n\nFür LIVE-Wünsche wähle Spotify als Musikquelle. Links und einzelne Treffer werden direkt eingereiht. Bei mehreren Treffern beantwortet der Zuschauer die Auswahlfrage mit einer Zahl. Wenn der automatische Chatversand aus ist, kopiere die Auswahlfrage unter Spotify und Musikwünsche in den Chat." },
        new[] { "YouTube Music und Pear Desktop", "Öffne Musik → YouTube Music und Musikwünsche. Über YouTube Music öffnen / anmelden gelangst du zur Website. Dort kannst du suchen und den Link eines Titels kopieren.\n\nFür die Desktop-Warteschlange muss Pear Desktop laufen. Aktiviere dort das Plugin API Server auf 127.0.0.1:26538. Klicke im Bot auf YouTube Music Desktop prüfen und bestätige die Verbindung in Pear Desktop.\n\nFüge einen Titellink ein und klicke In Desktop-Warteschlange. Mit YouTube Music als LIVE-Musikquelle können Titellinks eingereiht werden. Textwünsche kannst du über Wunsch suchen öffnen und anschließend den passenden Link einreihen." },
        new[] { "YouTube suchen, einreihen und abspielen", "Öffne Musik → YouTube. Gib einen Künstler oder Titel ein und klicke auf Suchen. Öffne in der Suche den passenden Treffer und klicke auf Offenes Video hinzufügen. Mit einem Videolink kannst du direkt Link hinzufügen wählen.\n\nDas erste Video startet bei freiem Player. Weitere Videos bleiben in der Warteschlange und folgen nach dem Ende des laufenden Videos. Mit Weiter überspringst du einen Titel. Stopp hält die Wiedergabe an. Öffne bei Bedarf den Player und klicke dort auf Wiedergabe, falls YouTube den automatischen Start blockiert.\n\nWenn YouTube als Musikquelle ausgewählt ist, reiht der Bot LIVE-Wünsche mit Videolink direkt ein. Wünsche als Titel stehen unter Offene Chatwünsche. Wähle den Eintrag, klicke Wunsch suchen, öffne den Treffer und füge ihn hinzu." },
        new[] { "LIVE-Auswertung und Benachrichtigungen", "Öffne LIVE-Auswertung, um die Zuschauerzahl laut TikTok und erkannte Aktivitäten wie Kommentare und Geschenke zu sehen. Die Auswertung hängt davon ab, welche Informationen TikTok im LIVE anzeigt.\n\nDie Glocke oben zeigt die Anzahl der Benachrichtigungen. Öffne sie für neue Musikwünsche und Updatehinweise. Dort kannst du Einträge auch löschen." },
        new[] { "Designs und Prüfintervalle", "Öffne Einstellungen → Designs. Wähle ein Design aus der Liste oder klicke auf eine Vorschau. Die Auswahl gilt direkt und wird gespeichert.\n\nÖffne Einstellungen → Prüfintervalle. Lege getrennt fest, wie oft der Bot nach Windows-Updates und nach deinem LIVE schaut. Die Werte reichen von 1 bis 240 Minuten. Die LIVE-Prüfung läuft bei eingeschaltetem LIVE automatisch prüfen." },
        new[] { "Updates installieren", "Öffne Einstellungen → Updates und klicke Nach Updates suchen. Wenn eine neuere Version verfügbar ist, klicke Update installieren.\n\nDie App zeigt beim Herunterladen den Fortschritt und, sobald berechenbar, die Restzeit. Anschließend prüft sie die Datei und startet das Windows-Setup. Deine Einstellungen und das Browserprofil werden weiterverwendet.\n\nWenn das Update in der App scheitert, prüfe Einstellungen → Fehlerlog. Du kannst alternativ das aktuelle Windows-Setup aus dem GitHub-Release erneut ausführen." },
        new[] { "Fehler finden und Protokoll löschen", "Bei rotem LIVE-Status prüfe zuerst den gespeicherten @Namen und ob der Stream tatsächlich live ist. Wenn Antworten nur als Vorschläge erscheinen, prüfe den Sendeschalter, das Bot-Konto und ob du in der TikTok-Webansicht schreiben kannst.\n\nBei Musikproblemen prüfe die gewählte Musikquelle. Spotify braucht ein aktives Wiedergabegerät und die Kontofreigabe. Bei mehreren Ergebnissen wartet der Bot auf die Auswahl. Für YouTube Music prüfe den API Server in Pear Desktop.\n\nUnter Einstellungen → Fehlerlog kannst du die Einträge aktualisieren, über Protokoll kopieren weitergeben oder über Fehlerlog löschen vollständig entfernen." },
    };

    internal BotHelp()
    {
        var title = new Label { Dock = DockStyle.Top, Height = 39, Text = "Anleitung zum TikTok-Bot", Font = AppTheme.HeadingFont };
        var chapter = new ThemeComboBox { Dock = DockStyle.Top, DropDownStyle = ComboBoxStyle.DropDownList, AccessibleName = "Kapitel auswählen" };
        var article = new TextBox { Dock = DockStyle.Fill, ReadOnly = true, Multiline = true,
            ScrollBars = ScrollBars.Vertical, BorderStyle = BorderStyle.None, AccessibleName = "Anleitung zum gewählten Kapitel" };
        var body = new Panel { Dock = DockStyle.Fill, Padding = new Padding(0, 16, 0, 0) };
        body.Controls.Add(article);
        foreach (var entry in Chapters) chapter.Items.Add(entry[0]);
        chapter.SelectedIndexChanged += delegate
        {
            if (chapter.SelectedIndex < 0) return;
            article.Text = Chapters[chapter.SelectedIndex][1].Replace("\n", "\r\n");
            article.SelectionStart = 0;
            article.ScrollToCaret();
        };
        Controls.AddRange(new Control[] { body, chapter, title });
        chapter.SelectedIndex = 0;
    }
}
